/* ШАБЛОНЫ ДЛЯ ЖИЗНИ: готовые таблицы для дома — бюджет на месяц и на год, привычки, планер
   недели, покупки, поездка, ремонт, тренировки, цели, подписки. Шаблон ложится на текущий лист
   с формулами, списками выбора, условным оформлением и диаграммой; жёлтые клетки — для ввода. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}
/* ===== Шаблон листа: таблица по описанию (общий кусок шаблонов, печатных форм и уроков) =====
   Описание: {имя, цвет, ш: [ширины столбцов, точек], р: [ряды значений с A1; '=…' — формула],
   с: [[область, стиль | имя стиля, доп]], о: [объединить], сп: [[область, 'значения,через,запятую']],
   ус: [[область, вид, значение, оформление]], д: [{обл, вид, где, ш, в, заг}], в: {номер строки: высота}} */
function тон(hex, доля){
  const n = parseInt(String(hex).slice(1), 16), r = n >> 16, g = (n >> 8) & 255, b = n & 255;
  const м = x => Math.round(255 - (255 - x) * доля).toString(16).padStart(2, '0');
  return '#' + м(r) + м(g) + м(b);
}
const ШСТИЛИ = цвет => ({
  заголовок: {b: 1, size: 16, color: цвет},
  подзаголовок: {i: 1, color: '#5b6474'},
  шапка: {b: 1, fill: тон(цвет, 0.16), color: '#1d2433', гр: РАМКА('тонкая', тон(цвет, 0.5)), align: 'center', valign: 'middle', wrap: 1},
  ячейка: {гр: РАМКА('тонкая', '#d5dae3')},
  ввод: {гр: РАМКА('тонкая', '#d5dae3'), fill: '#fffdf0'},
  итог: {b: 1, fill: тон(цвет, 0.09), гр: РАМКА('тонкая', тон(цвет, 0.5))},
  метка: {b: 1, color: '#3b4252'},
  заметка: {i: 1, color: '#7a8394', size: 9},
  акцент: {b: 1, color: цвет},
  деньги: {fmt: '#,##0.00 ₽'}, целое: {fmt: '#,##0'}, дата: {fmt: 'dd.mm.yyyy'}, процент: {fmt: '0%'},
});
const номерБуквы = б => { let c = 0; for(const ch of б) c = c * 26 + ch.charCodeAt(0) - 64; return c - 1; };
function разборОбласти(а){
  const [x, y] = String(а).split(':');
  const т = s => { const m = /^\$?([A-Z]+)\$?(\d+)$/.exec(s); return {r: +m[2] - 1, c: номерБуквы(m[1])}; };
  const a = т(x), b = т(y || x);
  return {r1: Math.min(a.r, b.r), c1: Math.min(a.c, b.c), r2: Math.max(a.r, b.r), c2: Math.max(a.c, b.c)};
}
const ЦВЕТ_RGB = hex => { const n = parseInt(String(hex).slice(1), 16); return Api.CreateColorFromRGB(n >> 16, (n >> 8) & 255, n & 255); };
/* Сколько места займёт шаблон: для проверки «лист пуст». */
function размерШаблона(ш){
  let R = (ш.р || []).length, C = Math.max(1, ...(ш.р || []).map(ряд => (ряд || []).length), (ш.ш || []).length);
  for(const [обл] of ш.с || []){ const o = разборОбласти(обл); R = Math.max(R, o.r2 + 1); C = Math.max(C, o.c2 + 1); }
  for(const д of ш.д || []){ const o = разборОбласти(д.где); R = Math.max(R, o.r1 + Math.ceil((д.в || 260) / 24)); C = Math.max(C, o.c1 + Math.ceil((д.ш || 420) / 92)); }
  return {R, C};
}
async function разложитьШаблон(ш, {спросить = true} = {}){
  const {R, C} = размерШаблона(ш);
  if(спросить && !(await областьПуста(0, 0, R + 1, C + 1))){
    const да = await диалог.вопрос('На листе уже есть данные. Положить «' + ш.имя + '» поверх? Надёжнее — добавить пустой лист и открыть панель снова.');
    if(!да) return false;
  }
  const л = Api.GetActiveSheet(), ст = ШСТИЛИ(ш.цвет || '#2b6cb0');
  /* оформление: области ложатся по порядку, позднее дополняет раннее */
  const стили = new Map();
  for(const [обл, вид, доп] of ш.с || []){
    const o = разборОбласти(обл), база = typeof вид === 'string' ? вид.split(' ').reduce((s, и) => Object.assign(s, ст[и] || {}), {}) : (вид || {});
    for(let r = o.r1; r <= o.r2; r++) for(let c = o.c1; c <= o.c2; c++){ const к = r + ',' + c; стили.set(к, Object.assign({}, стили.get(к) || {}, база, доп || {})); }
  }
  (ш.р || []).forEach((ряд, r) => (ряд || []).forEach((v, c) => {
    if(v === null || v === undefined || v === '') return;
    const к = клетка(r, c);
    if(typeof v === 'string' && v[0] === '=') к.формула = v.slice(1); else к.значение = v;
  }));
  for(const [к, s] of стили){ const [r, c] = к.split(',').map(Number); клетка(r, c).стиль = s; }
  (ш.ш || []).forEach((px, c) => { if(px) ширинаСтолбца(c, px); });
  let высоты = false;
  for(const r in ш.в || {}){ высотаСтроки(+r - 1, ш.в[r]); высоты = true; }
  for(const а of ш.о || []) try { л.GetRange(а).Merge(false); } catch(e){}
  for(const [а, список] of ш.сп || []) try { л.GetRange(а).GetValidation().Add('xlValidateList', 'xlValidAlertStop', null, '"' + список + '"'); } catch(e){}
  for(const [а, вид, знач, оф] of ш.ус || []){
    try {
      const ф = л.GetRange(а).GetFormatConditions();
      const ОП = {'<': 'xlLess', '>': 'xlGreater', '<=': 'xlLessEqual', '>=': 'xlGreaterEqual', '=': 'xlEqual', '<>': 'xlNotEqual'};
      const у = ОП[вид] ? ф.Add('xlCellValue', ОП[вид], String(знач)) : вид === 'формула' ? ф.Add('xlExpression', знач) : вид === 'непусто' ? ф.Add('xlNoBlanksCondition') : вид === 'шкала' ? ф.AddColorScale() : null;
      if(у && оф){
        у.SetFillColor(оф.fill ? ЦВЕТ_RGB(оф.fill) : 'No Fill');
        if(оф.color) у.SetFontColor(ЦВЕТ_RGB(оф.color));
        if(оф.b) у.SetBold(true);
        if(оф.strike) у.SetStrikeout(true);
      }
    } catch(e){ сообщить('Условное оформление ' + а + ': ' + e.message); }
  }
  for(const д of ш.д || []){
    try {
      const где = разборОбласти(д.где);
      const ch = л.AddChart(д.обл, !!д.построкам, д.вид || 'bar', 2, (д.ш || 420) * 9525, (д.в || 260) * 9525, где.c1, 0, где.r1, 0);
      if(д.заг) ch.SetTitle(д.заг);
    } catch(e){ сообщить('Диаграмма: ' + e.message); }
  }
  if(ш.печать) try { лист().запомнить('печать', Object.assign({область: null, шапка: 0, ориентация: 'portrait', бумага: 'A4', уместить: true, масштаб: 100, сетка: false, заголовки: false, название: false}, ш.печать)); } catch(e){}
  if(высоты) await обновитьВысоты();
  if(ш.курсор) try { диапазон(ш.курсор).выделить(); } catch(e){}
  return true;
}
/* Миниатюра для галереи: лист со шапкой и строками по ширинам шаблона. */
function миниатюраЛиста(ш){
  const цвет = ш.цвет || '#2b6cb0', ш0 = (ш.ш || [92, 92, 92, 92]).slice(0, 8), всего = ш0.reduce((s, x) => s + (x || 92), 0);
  const W = 120, H = 84, x0 = 8, ширП = W - 16;
  let x = x0, линии = '';
  ш0.forEach(px => { x += (px || 92) / всего * ширП; if(x < W - 9) линии += '<line x1="' + x.toFixed(1) + '" y1="26" x2="' + x.toFixed(1) + '" y2="76" stroke="#d5dae3" stroke-width="0.6"/>'; });
  let ряды = '';
  for(let y = 34; y <= 76; y += 7) ряды += '<line x1="8" y1="' + y + '" x2="112" y2="' + y + '" stroke="#d5dae3" stroke-width="0.6"/>';
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '">'
    + '<rect x="0.5" y="0.5" width="' + (W - 1) + '" height="' + (H - 1) + '" rx="6" fill="#fff" stroke="#c9d1de"/>'
    + '<rect x="8" y="9" width="60" height="7" rx="2" fill="' + цвет + '"/>'
    + '<rect x="8" y="26" width="104" height="8" fill="' + тон(цвет, 0.25) + '"/>'
    + ряды + линии + (ш.д && ш.д.length ? '<circle cx="98" cy="13" r="7" fill="' + тон(цвет, 0.5) + '"/><path d="M98 13 L98 6 A7 7 0 0 1 104.6 15.2 Z" fill="' + цвет + '"/>' : '') + '</svg>';
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}
/* ===== конец куска «шаблон листа» ===== */

const МЕСЯЦЫ = ['Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь', 'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'];
const МЕС3 = ['Янв', 'Фев', 'Мар', 'Апр', 'Май', 'Июн', 'Июл', 'Авг', 'Сен', 'Окт', 'Ноя', 'Дек'];
const сейчас = () => { const д = new Date(); return {м: д.getMonth(), г: д.getFullYear()}; };
const Б = c => БУКВА(c);
const пустые = n => Array(n).fill('');

const ШАБЛОНЫ = [
  /* 1 */ () => {
    const {м, г} = сейчас();
    const доходы = ['Зарплата', 'Подработка', 'Пособия и выплаты', 'Проценты и кешбэк', 'Прочие доходы'];
    const расходы = ['Жильё и ЖКУ', 'Продукты', 'Транспорт', 'Связь и интернет', 'Здоровье', 'Одежда и обувь', 'Дети', 'Образование', 'Кафе и доставка', 'Развлечения и хобби', 'Подарки', 'Кредиты и долги', 'Накопления', 'Прочее'];
    const р = [['Семейный бюджет'], ['Месяц:', МЕСЯЦЫ[м] + ' ' + г], [], ['Доходы', 'План', 'Факт', 'Разница']];
    доходы.forEach((и, i) => р.push([и, '', '', '=C' + (5 + i) + '-B' + (5 + i)]));
    р.push(['Итого доходов', '=СУММ(B5:B9)', '=СУММ(C5:C9)', '=C10-B10'], [], ['Расходы', 'План', 'Факт', 'Осталось']);
    расходы.forEach((и, i) => р.push([и, '', '', '=B' + (13 + i) + '-C' + (13 + i)]));
    р.push(['Итого расходов', '=СУММ(B13:B26)', '=СУММ(C13:C26)', '=B27-C27'], [], ['Остаток (доходы − расходы)', '=B10-B27', '=C10-C27'],
      ['Доля накоплений в доходе', '=ЕСЛИОШИБКА(B25/B10;0)', '=ЕСЛИОШИБКА(C25/C10;0)'], [],
      ['Жёлтые клетки — для ввода. «Осталось» по расходам: плюс — уложились в план, минус — перерасход.']);
    return {имя: 'Семейный бюджет на месяц', группа: 'Деньги', про: 'Доходы и расходы по статьям: план, факт, остаток и доля накоплений; диаграмма план-факт по расходам.', цвет: '#2f855a',
      ш: [230, 110, 110, 110], р, в: {1: 34},
      с: [['A1', 'заголовок'], ['A2', 'метка'], ['B2', 'акцент'], ['A4:D4', 'шапка'], ['A12:D12', 'шапка'], ['A5:A9', 'ячейка'], ['B5:C9', 'ввод деньги'], ['D5:D9', 'ячейка деньги'],
        ['A10:D10', 'итог деньги'], ['A13:A26', 'ячейка'], ['B13:C26', 'ввод деньги'], ['D13:D26', 'ячейка деньги'], ['A27:D27', 'итог деньги'],
        ['A29:C29', 'итог деньги'], ['A30', 'метка'], ['B30:C30', 'ячейка процент'], ['A32', 'заметка']],
      ус: [['D5:D9', '<', 0, {color: '#c53030'}], ['D13:D26', '<', 0, {color: '#c53030', b: 1}], ['B29:C29', '<', 0, {color: '#c53030'}]],
      д: [{обл: 'A12:C26', вид: 'bar', где: 'F4', ш: 520, в: 360, заг: 'Расходы: план и факт'}], курсор: 'B5'};
  },
  /* 2 */ () => {
    const {г} = сейчас();
    const доходы = ['Зарплата', 'Подработка', 'Прочие доходы'], расходы = ['Жильё и ЖКУ', 'Продукты', 'Транспорт', 'Связь', 'Здоровье', 'Одежда', 'Дети и учёба', 'Отдых и хобби', 'Кредиты', 'Прочее'];
    const N = 12, кИт = Б(N + 1), кСр = Б(N + 2);
    const ср = n => '=ЕСЛИОШИБКА(СРЗНАЧ(B' + n + ':' + Б(N) + n + ');0)';
    const ряд = (имя, n) => [имя, ...пустые(N), '=СУММ(B' + n + ':' + Б(N) + n + ')', ср(n)];
    const итог = (имя, n, a, b) => [имя, ...Array.from({length: N}, (_, j) => '=СУММ(' + Б(1 + j) + a + ':' + Б(1 + j) + b + ')'), '=СУММ(B' + n + ':' + Б(N) + n + ')', ср(n)];
    const р = [['Бюджет на ' + г + ' год'], [], ['Доходы', ...МЕС3, 'Итого', 'В среднем']];
    доходы.forEach((и, i) => р.push(ряд(и, 4 + i)));
    р.push(итог('Итого доходов', 7, 4, 6), [], ['Расходы', ...МЕС3, 'Итого', 'В среднем']);
    расходы.forEach((и, i) => р.push(ряд(и, 10 + i)));
    р.push(итог('Итого расходов', 20, 10, 19), [], ['Сводка', ...МЕС3, 'Итого', ''],
      ['Доходы', ...Array.from({length: N}, (_, j) => '=' + Б(1 + j) + '7'), '=' + кИт + '7'],
      ['Расходы', ...Array.from({length: N}, (_, j) => '=' + Б(1 + j) + '20'), '=' + кИт + '20'],
      ['Остаток', ...Array.from({length: N}, (_, j) => '=' + Б(1 + j) + '23-' + Б(1 + j) + '24'), '=' + кИт + '23-' + кИт + '24'],
